import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); String s = br.readLine().trim(); int firstOne = -1; for (int i = 0; i <= n - 3; i++) { if (s.charAt(i) == '1') { firstOne = i; break; } } if (firstOne == -1) { out.println(s); } else { StringBuilder sb = new StringBuilder(); sb.append(s.substring(0, firstOne)); sb.append("100"); sb.append(s.substring(firstOne + 3)); out.println(sb.toString()); } } } out.flush(); out.close(); } }